mapper.select:
select id, source_topic_id, idempotency_key, new_topic_id, create_by, create_time
  from topic_edition_reopen_request
 where source_topic_id = #{sourceTopicId} and idempotency_key = #{idempotencyKey}

mapper.update:
update topic_edition_reopen_request
   set new_topic_id = #{newTopicId}
 where id = #{requestId} and new_topic_id is null
